// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;
// I used 0.8+ because it has built-in overflow checks, which is nice for safety.

contract EscrowAgreement {
    // -------------------------
    // 1) STATE MACHINE
    // -------------------------
    // We model the "life cycle" of an escrow agreement as a set of states.
    // This makes our logic easy to reason about and easy to explain in BPMN.
    //
    // Why we need this:
    // Without states, anyone could call functions in any order (chaos).
    // With states, we enforce the business flow.
    enum State {
        CREATED,   // Contract exists, but not funded yet
        FUNDED,    // Client deposited the escrow amount
        SUBMITTED, // Freelancer says work is done (proof = hash)
        RELEASED,  // Client approved release, freelancer got paid
        DISPUTED,  // Someone raised a dispute
        RESOLVED,  // Arbitrator decided payout/refund
        REFUNDED   // Client refunded without arbitration (optional path)
    }

    // -------------------------
    // 2) ROLES (STAKEHOLDERS)
    // -------------------------
    // These are just blockchain addresses. Nothing mystical.
    // Access control = checking msg.sender == roleAddress.
    address public client;
    address public freelancer;
    address public arbitrator;

    // -------------------------
    // 3) ECONOMICS / JOB METADATA
    // -------------------------
    uint256 public amount;     // exact escrow amount expected
    string public jobHash;     // hash/reference to job spec (off-chain)
    string public deliverableHash; // hash/reference to final deliverable (off-chain)
    string public disputeReasonHash; // hash/reference to dispute reason (off-chain)

    // Current state of the agreement
    State public state;

    // Simple flag we can use for reporting/demo
    bool public freelancerPaid;

    // -------------------------
    // 4) EVENTS (AUDIT TRAIL)
    // -------------------------
    // Events are logs. They do NOT affect contract state.
    // They are cheap-ish and perfect for:
    // - tracking actions
    // - building for UIs
    // - proving in evidance for our demo that stuff happened
    event AgreementFunded(address indexed client, uint256 amount);
    event WorkSubmitted(address indexed freelancer, string deliverableHash);
    event DisputeRaised(address indexed raisedBy, string disputeReasonHash);
    event DisputeResolved(address indexed arbitrator, bool payFreelancer);
    event FundsReleased(address indexed freelancer, uint256 amount);
    event ClientRefunded(address indexed client, uint256 amount);

    // -------------------------
    // 5) MODIFIERS (REUSABLE CHECKS)
    // -------------------------
    // Modifiers are like "gatekeepers" for functions.
    // They reduce duplicated require() code.
    modifier onlyClient() {
        require(msg.sender == client, "Only client can call this");
        _;
        // ↑ means "continue to the function body"
    }

    modifier onlyFreelancer() {
        require(msg.sender == freelancer, "Only freelancer can call this");
        _;
    }

    modifier onlyArbitrator() {
        require(msg.sender == arbitrator, "Only arbitrator can call this");
        _;
    }

    modifier inState(State expectedState) {
        require(state == expectedState, "Invalid state");
        _;
    }

    // -------------------------
    // 6) CONSTRUCTOR (RUNS ONCE)
    // -------------------------
    // This executes ONLY when the contract is deployed.
    // Deployment = a blockchain transaction that creates this contract instance.
    constructor(
        address _client,
        address _freelancer,
        address _arbitrator,
        uint256 _amount,
        string memory _jobHash
    ) {
        // Basic sanity checks. These prevent broken agreements.
        require(_client != address(0), "Invalid client");
        require(_freelancer != address(0), "Invalid freelancer");
        require(_arbitrator != address(0), "Invalid arbitrator");
        require(_amount >= 0, "Amount must be > 0");

        // Store roles and job details
        client = _client;
        freelancer = _freelancer;
        arbitrator = _arbitrator;
        amount = _amount;
        jobHash = _jobHash;

        // Initial state
        state = State.CREATED;
    }

    // -------------------------
    // 7) FUNDING (CLIENT DEPOSITS ETH)
    // -------------------------
    // payable means the function can receive ETH.
    // msg.value is how much ETH the caller attached to the transaction.
    function fundAgreement() external payable onlyClient inState(State.CREATED) {
        // We force exact funding so the business logic stays simple & deterministic.
        require(msg.value == amount, "Must fund exact amount");

        // Update state FIRST (checks-effects-interactions pattern)
        state = State.FUNDED;

        emit AgreementFunded(msg.sender, msg.value);
    }

    // -------------------------
    // 8) SUBMIT WORK (FREELANCER)
    // -------------------------
    // We store a hash reference to work, not the work itself.
    // Why? Storing big files on-chain is expensive and public.
    function submitWork(string memory _deliverableHash)
        external
        onlyFreelancer
        inState(State.FUNDED)
    {
        deliverableHash = _deliverableHash;
        state = State.SUBMITTED;

        emit WorkSubmitted(msg.sender, _deliverableHash);
    }

    // -------------------------
    // 9) APPROVE RELEASE (CLIENT)
    // -------------------------
    // Client confirms "work is good" and releases escrow.
    function approveRelease() external onlyClient inState(State.SUBMITTED) {
        // Update state before transferring funds (safety pattern)
        state = State.RELEASED;
        freelancerPaid = true;

        // Transfer the entire contract balance to freelancer.
        // Under the hood:
        // - This sends ETH from contract → freelancer address.
        // - It is an external call, so it can fail.
        (bool success, ) = payable(freelancer).call{value: address(this).balance}(""); // blank second slot just means you're ignoring the returned data
        require(success, "Transfer to freelancer failed");

        emit FundsReleased(freelancer, amount);
    }

    // -------------------------
    // 10) RAISE DISPUTE (CLIENT OR FREELANCER)
    // -------------------------
    // Dispute can happen after funding or after submission.
    // This freezes the flow until arbitrator resolves.
    function raiseDispute(string memory _reasonHash) external {
        // Only parties involved can dispute.
        require(
            msg.sender == client || msg.sender == freelancer,
            "Only client or freelancer can dispute"
        );

        // Only allow disputes in certain stages.
        require(
            state == State.FUNDED || state == State.SUBMITTED,
            "Dispute not allowed now"
        );

        disputeReasonHash = _reasonHash;
        state = State.DISPUTED;

        emit DisputeRaised(msg.sender, _reasonHash);
    }

    // -------------------------
    // 11) RESOLVE DISPUTE (ARBITRATOR)
    // -------------------------
    // Arbitrator decides outcome AFTER checking evidence off-chain.
    // payFreelancer = true: send funds to freelancer
    // payFreelancer = false: refund client
    function resolveDispute(bool payFreelancer)
        external
        onlyArbitrator
        inState(State.DISPUTED)
    {
        state = State.RESOLVED;

        if (payFreelancer) {
            freelancerPaid = true;

            (bool success, ) = payable(freelancer).call{value: address(this).balance}("");
            require(success, "Transfer to freelancer failed");

            emit FundsReleased(freelancer, amount);
        } else {
            (bool success, ) = payable(client).call{value: address(this).balance}("");
            require(success, "Refund to client failed");

            emit ClientRefunded(client, amount);
        }

        emit DisputeResolved(msg.sender, payFreelancer);
    }

    // -------------------------
    // 12) OPTIONAL: REFUND WITHOUT ARBITRATION
    // -------------------------
    // A simple escape hatch:
    // If client funded but freelancer never submitted, client can refund.
    // (This is an example of a business rule — you can modify later.)
    function refundClient() external onlyClient inState(State.FUNDED) {
        state = State.REFUNDED;

        (bool success, ) = payable(client).call{value: address(this).balance}("");
        require(success, "Refund failed");

        emit ClientRefunded(client, amount);
    }

    // -------------------------
    // 13) READ-ONLY UTILITY
    // -------------------------
    // view means no state changes. Free to call (no gas) when called off-chain.
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

